// LoadNode loads the gameServerBackup's Node into the .R struct
func (o *GameServerBackup) LoadNode(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Node = nil
	o.R.Loaded.Node = false

	related, err := o.Node(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.GameServerBackups = GameServerBackupSlice{o}

	o.R.Node = related
	o.R.Loaded.Node = true
	return nil
}

// LoadNode loads the gameServerBackup's Node into the .R struct
func (os GameServerBackupSlice) LoadNode(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	nodes, err := os.Node(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Node = nil
		o.R.Loaded.Node = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	gameServerBackupByKey := make(map[string][]*GameServerBackup, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		gameServerBackupByKey[o.NodeID] = append(gameServerBackupByKey[o.NodeID], o)
	}

	for _, rel := range nodes {

		owners, ok := gameServerBackupByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Node != nil {
				continue
			}

			rel.R.GameServerBackups = append(rel.R.GameServerBackups, o)

			o.R.Node = rel

		}
	}

	return nil
}

